    doc.setTextColor(0);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(9); // Increased from 8
    doc.text("11th Floor, Logistic Hub Private Limited\nGodrej One, Pirojshanagar, Vikhroli\nMumbai Maharashtra 400079\nIndia", 110, 22, { align: "center", lineHeightFactor: 1.2 });

    doc.setFont("helvetica", "bold");
    doc.setFontSize(9.5);
    doc.text("GSTIN 27AAJCA9880A1ZJ", 110, 41, { align: "center" });
